package com.beatoflove.standardcalculator;
import java.util.*;
/** Weighted univariate and paired data; no expansion of frequency counts. */
public final class FormulaStats {
    public enum Model { LINEAR, LOG, EXP, POWER, INVERSE, QUADRATIC }
    public static final class Row {public final double x,y;public final int w;public Row(double x,double y,int w){if(!Double.isFinite(x)||!Double.isFinite(y)||w<1||w>1000000)throw new IllegalArgumentException("ข้อมูลหรือความถี่ไม่ถูกต้อง");this.x=x;this.y=y;this.w=w;}}
    public static List<Row> parse(String text, boolean paired){List<Row> r=new ArrayList<>();int line=0;for(String s:text.split("\\R")){line++;if(s.trim().isEmpty())continue;try{String[] a=s.trim().split("[,;\\s]+");int base=paired?2:1;if(a.length<base||a.length>base+1)throw new IllegalArgumentException();r.add(new Row(Double.parseDouble(a[0]),paired?Double.parseDouble(a[1]):0,a.length==base?1:Integer.parseInt(a[base])));}catch(Exception e){throw new IllegalArgumentException("ตรวจสอบข้อมูลบรรทัด "+line);}}if(r.isEmpty()||r.size()>5000)throw new IllegalArgumentException("ต้องมีข้อมูล 1–5000 แถว");return r;}
    public static Map<String,Double> summarize(List<Row> rows,boolean paired){double n=0,sx=0,sy=0,sxx=0,syy=0,sxy=0,sxxx=0,sxxxx=0,sxxy=0;for(Row r:rows){double x=r.x,y=r.y,w=r.w;n+=w;sx+=w*x;sy+=w*y;sxx+=w*x*x;syy+=w*y*y;sxy+=w*x*y;sxxx+=w*x*x*x;sxxxx+=w*x*x*x*x;sxxy+=w*x*x*y;}if(n==0)throw new IllegalArgumentException("ไม่มีข้อมูล");double mx=sx/n,my=sy/n,xx=0,yy=0,xy=0;for(Row r:rows){double dx=r.x-mx,dy=r.y-my;xx+=r.w*dx*dx;yy+=r.w*dy*dy;xy+=r.w*dx*dy;}Map<String,Double> m=new LinkedHashMap<>();m.put("n",n);m.put("sumx",sx);m.put("sumx2",sxx);m.put("meanx",mx);m.put("sigmax",Math.sqrt(xx/n));m.put("sdx",n>1?Math.sqrt(xx/(n-1)):Double.NaN);if(paired){m.put("sumy",sy);m.put("sumy2",syy);m.put("sumxy",sxy);m.put("sumx3",sxxx);m.put("sumx4",sxxxx);m.put("sumx2y",sxxy);m.put("meany",my);m.put("sigmay",Math.sqrt(yy/n));m.put("sdy",n>1?Math.sqrt(yy/(n-1)):Double.NaN);m.put("cov",n>1?xy/(n-1):Double.NaN);}return m;}
    public static final class Fit {public final Model model;public final double a,b,c,r;Fit(Model m,double a,double b,double c,double r){model=m;this.a=FormulaEngine.finite(a);this.b=FormulaEngine.finite(b);this.c=FormulaEngine.finite(c);this.r=r;}
        public double predict(double x){switch(model){case LOG:return FormulaEngine.finite(a+b*Math.log(x));case EXP:return FormulaEngine.finite(a*Math.exp(b*x));case POWER:FormulaEngine.require(x>0,"x ต้องมากกว่า 0");return FormulaEngine.finite(a*Math.pow(x,b));case INVERSE:return FormulaEngine.finite(a+b/x);case QUADRATIC:return FormulaEngine.finite(a+b*x+c*x*x);default:return FormulaEngine.finite(a+b*x);}}
        public double[] inverse(double y){if(model==Model.QUADRATIC&&c!=0){double d=b*b-4*c*(a-y);FormulaEngine.require(d>=0,"ไม่มีคำตอบจริง");return new double[]{FormulaEngine.finite((-b+Math.sqrt(d))/(2*c)),FormulaEngine.finite((-b-Math.sqrt(d))/(2*c))};}FormulaEngine.require(b!=0,"ไม่สามารถประมาณ x ได้เมื่อ B=0");double x;switch(model){case LOG:x=Math.exp((y-a)/b);break;case EXP:x=Math.log(y/a)/b;break;case POWER:x=Math.exp(Math.log(y/a)/b);break;case INVERSE:x=b/(y-a);break;default:x=(y-a)/b;}return new double[]{FormulaEngine.finite(x)};}}
    public static Fit fit(List<Row> rows, Model model){if(rows.size()<2)throw new IllegalArgumentException("ต้องมีอย่างน้อย 2 แถว");boolean logx=model==Model.LOG||model==Model.POWER,logy=model==Model.EXP||model==Model.POWER;double n=0,mx=0,my=0;List<Row> t=new ArrayList<>();for(Row r:rows){if(logx&&r.x<=0||logy&&r.y<=0||model==Model.INVERSE&&r.x==0)throw new IllegalArgumentException("ข้อมูลไม่อยู่ในโดเมนของสมการ");double x=logx?Math.log(r.x):model==Model.INVERSE?1/r.x:r.x,y=logy?Math.log(r.y):r.y;t.add(new Row(x,y,r.w));n+=r.w;mx+=r.w*x;my+=r.w*y;}mx/=n;my/=n;double s2=0,s3=0,s4=0,xy=0,x2y=0,yy=0;for(Row q:t){double x=q.x-mx,y=q.y-my,w=q.w;s2+=w*x*x;s3+=w*x*x*x;s4+=w*x*x*x*x;xy+=w*x*y;x2y+=w*x*x*y;yy+=w*y*y;}if(!(s2>0))throw new IllegalArgumentException("ค่า X ต้องแตกต่างกัน");double b=xy/s2,c=0,a=my-b*mx;double r=yy>0?Math.max(-1,Math.min(1,xy/Math.sqrt(s2*yy))):Double.NaN;if(model==Model.QUADRATIC){double z=s4-s2*s2/n,det=s2*z-s3*s3;if(rows.size()<3||!(det>0)||det<=Math.abs(s2*z)*1e-14)throw new IllegalArgumentException("Quadratic ต้องมี X ที่แตกต่างกันอย่างน้อย 3 ค่า");double bc=(xy*z-x2y*s3)/det;c=(s2*x2y-s3*xy)/det;b=bc-2*c*mx;a=my-c*s2/n-bc*mx+c*mx*mx;r=Double.NaN;}return new Fit(model,logy?Math.exp(a):a,b,c,r);}
}
